python
def receiptArithmeticThresholdFile(readings, k):
    a=readings
    out=[]
    for x in a: out.append(2*x+3)
    return sum(x>=k for x in out)


java
class Solution {
  public int receiptArithmeticThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a)out.add(2*x+3);}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
